/**
 * "Wawitas" as the shelter actually draws it — a brush logotype, supplied with
 * the mark and adopted on 2026-09-19.
 *
 * It replaces a Fraunces 900 setting of the same word in the header. That was
 * always a stand-in for a logotype the organisation already owned, and a brush
 * script is not something a variable font can imitate.
 *
 * SHELTER-SPECIFIC ARTWORK. A fork either replaces this path with its own
 * logotype or sets `hasWordmark: false` in src/config/shelter.ts, which puts
 * the type-set treatment back. Everything else is driven from that config, so
 * this file and Brand.tsx are the only two carrying drawn artwork.
 *
 * Same inverted-trace provenance and the same two corrections as Brand.tsx —
 * read the note there before re-importing either.
 */

interface WordmarkProps {
  /** Rendered WIDTH in px. Height follows the artwork's 5.8007 ratio. */
  size?: number;
  /** Any CSS colour. Inherits by default, so it matches whatever sets it. */
  color?: string;
  /**
   * The word the artwork spells. Pass it wherever the logotype STANDS IN for
   * text a reader would otherwise get — a drawn word is invisible to a screen
   * reader and to a crawler. Omit it only where the same word is already in
   * the accessible name of an enclosing element.
   */
  title?: string;
  className?: string;
}

